python3 -I - <<'EOF'
import math,re
lines=open('docs/design.md').read().split('\n')
incode=False; rl=0.0; para=''
def flush(p):
    global rl
    if p.strip(): rl+=max(1,math.ceil(len(p.strip())/95))
for ln in lines:
    if ln.startswith('```'):
        flush(para); para=''; incode=not incode; rl+=1; continue
    if incode: rl+=1; continue
    if ln.strip()=='' :
        flush(para); para=''; rl+=0.6; continue
    if ln.lstrip().startswith('|') or ln.startswith('#'):
        flush(para); para=''
        rl+=max(1,math.ceil(len(ln)/95)); continue
    para+=' '+ln
flush(para)
print(f"rendered lines ~{rl:.0f} -> pages @46 = {rl/46:.1f}, @52 = {rl/52:.1f}")
EOF

