    assert.equal(rows[0]?.state, "failed");
    assert.match(String(rows[0]?.lastError), /INVALID_FIELD: city/);
    // Never deleted: the row keeps its error as the record that a human is needed.
    assert.equal(rows.length, 1);
  });
});
